"use client";

import type { IconName } from "@once-ui-system/core";
import { Column, type Flex, Line, Nav, NavGroup, NavItem, NavSection, selectNavHref } from "@once-ui-system/core";
import { usePathname } from "next/navigation";
import { useEffect, useState } from "react";
import { useOrg } from "@/components/OrgProvider";
import { DEMO_ORG_SLUG, orgPath } from "@/lib/orgs/types";

interface SidebarProps extends React.ComponentProps<typeof Flex> {}

/**
 * The product navigation as data. `subPath` is relative to the current
 * organization — every entry here is org-scoped, so the slug is applied in
 * one place below rather than written into each link.
 *
 * The resolved href is what the current-page match runs on: `selectNavHref`
 * picks the longest href that prefixes the path, so a nested route lights
 * its section up and a sibling never does. Entries without a `subPath` are
 * placeholders for routes the app has not built yet — the template shows
 * the shape, not a finished product.
 */
type Entry = { label: string; subPath?: string; icon?: IconName; indicator?: boolean };

const home: Entry[] = [
  { label: "Dashboard", subPath: "", icon: "home" },
  { label: "Analytics", subPath: "/analytics", icon: "trend" },
  { label: "Reports", icon: "pages", indicator: true },
];

const manage: Entry[] = [
  { label: "Users", subPath: "/users" },
  { label: "Roles" },
  { label: "Permissions" },
];

const projects: Entry[] = [{ label: "Overview" }, { label: "My projects" }];

/**
 * The top links are where people spend the day; everything behind them sits
 * in groups that fold away, so the sidebar stays short as the app grows.
 */
const groups: { key: string; label: string; icon: IconName; entries: Entry[] }[] = [
  { key: "manage", label: "Manage", icon: "people", entries: manage },
  { key: "projects", label: "Projects", icon: "folder", entries: projects },
];

const Sidebar: React.FC<SidebarProps> = ({ ...flex }) => {
  const pathname = usePathname() ?? "";
  // The URL segment, not the loaded organization: the nav has to render on
  // the first paint and in demo mode, both of which happen before — or
  // entirely without — the org list arriving.
  const { slug } = useOrg();
  const org = slug ?? DEMO_ORG_SLUG;

  const entries = [...home, ...manage, ...projects];
  const hrefOf = (entry: Entry) =>
    entry.subPath === undefined ? undefined : orgPath(org, entry.subPath);
  const current = selectNavHref(
    pathname,
    entries.flatMap((entry) => {
      const href = hrefOf(entry);
      return href ? [href] : [];
    }),
  );

  const item = (entry: Entry, withIcon: boolean) => {
    const href = hrefOf(entry);
    return (
      <NavItem
        key={entry.label}
        href={href}
        icon={withIcon ? entry.icon : undefined}
        label={entry.label}
        indicator={entry.indicator}
        selected={href !== undefined && href === current}
      />
    );
  };

  // The group holding the current page opens itself; the rest keep whatever
  // the person left them at.
  const routeGroup = groups.find((group) =>
    group.entries.some((entry) => {
      const href = hrefOf(entry);
      return href !== undefined && href === current;
    }),
  )?.key;
  const [open, setOpen] = useState<Record<string, boolean>>(
    routeGroup ? { [routeGroup]: true } : {},
  );
  useEffect(() => {
    if (routeGroup) setOpen((state) => ({ ...state, [routeGroup]: true }));
  }, [routeGroup]);

  return (
    <Column data-transition="none" fillWidth paddingX="4" paddingY="20" {...flex}>
      <Nav density="compact" fill overflowY="auto" padding="4" aria-label="Product">
        {home.map((entry) => item(entry, true))}

        <Line background="neutral-alpha-medium" marginY="12" />
        <NavSection label="Workspace">
          {groups.map((group) => (
            <NavGroup
              key={group.key}
              label={group.label}
              icon={group.icon}
              open={!!open[group.key]}
              onToggle={() => setOpen((state) => ({ ...state, [group.key]: !state[group.key] }))}
            >
              {group.entries.map((entry) => item(entry, false))}
            </NavGroup>
          ))}
        </NavSection>
      </Nav>
    </Column>
  );
};

export { Sidebar };

"use client";

import { createContext, useContext, useEffect, useMemo, useState } from "react";
import { createClient } from "@/lib/sb/client";
import { isSupabaseConfigured } from "@/lib/sb/config";
import { apiErrorMessage } from "@/lib/api-error-message";

type Profile = {
  avatar_url: string | null;
  username: string | null;
  bio: string | null;
};

type UserContextValue = {
  loading: boolean;
  error: string | null;
  profile: Profile | null;
  userEmail: string | null;
  roleId: "member" | "admin" | null;
  roleRank: number | null;
  refresh: () => Promise<void>;
};

const UserContext = createContext<UserContextValue | undefined>(undefined);

export function UserProvider({ children }: { children: React.ReactNode }) {
  // In demo mode (no Supabase env) there is no user to load — start settled.
  const configured = isSupabaseConfigured();
  const [loading, setLoading] = useState(configured);
  const [error, setError] = useState<string | null>(null);
  const [profile, setProfile] = useState<Profile | null>(null);
  const [userEmail, setUserEmail] = useState<string | null>(null);
  const [roleId, setRoleId] = useState<"member" | "admin" | null>(null);
  const [roleRank, setRoleRank] = useState<number | null>(null);

  const load = async () => {
    if (!configured) return;
    try {
      setLoading(true);
      setError(null);
      // No session cookie: signed out. Asking the API would only log a 401
      // in the console of every signed-out page.
      const { data: session } = await createClient().auth.getSession();
      if (!session.session) {
        setProfile(null);
        setUserEmail(null);
        setRoleId(null);
        setRoleRank(null);
        return;
      }
      // Try up to 3 times with small backoff to allow session cookies to settle
      let lastErr: Error | null = null;
      for (let attempt = 0; attempt < 3; attempt++) {
        try {
          const res = await fetch("/api/profile", {
            credentials: "include",
            cache: "no-store",
          });
          if (res.status === 401) {
            // Signed out — a normal state, not an error worth surfacing
            setProfile(null);
            setUserEmail(null);
            setRoleId(null);
            setRoleRank(null);
            lastErr = null;
            break;
          }
          if (!res.ok) {
            const body = await res.json().catch(() => ({}));
            throw new Error(apiErrorMessage(body, `Request failed (${res.status})`));
          }
          const data = (await res.json()) as {
            profile: Profile;
            email?: string | null;
            roleId?: "member" | "admin" | null;
            roleRank?: number | null;
          };
          setProfile(data.profile ?? null);
          setUserEmail(data.email ?? null);
          setRoleId(data.roleId ?? null);
          setRoleRank(data.roleRank ?? null);
          lastErr = null;
          break;
        } catch (e) {
          lastErr = e instanceof Error ? e : new Error(String(e));
          // small delay before retrying
          await new Promise((r) => setTimeout(r, 300 * (attempt + 1)));
        }
      }
      if (lastErr) throw lastErr;
    } catch (e) {
      setError(e instanceof Error ? e.message : "Failed to fetch user profile");
      setProfile(null);
      setUserEmail(null);
      setRoleId(null);
      setRoleRank(null);
    } finally {
      setLoading(false);
    }
  };

  // biome-ignore lint/correctness/useExhaustiveDependencies: subscribe once on mount; load only reads setters
  useEffect(() => {
    if (!configured) return;
    void load();
    // Listen for auth state changes to proactively refresh user/profile
    const supabase = createClient();
    const { data: sub } = supabase.auth.onAuthStateChange((_event) => {
      // On SIGNED_IN, TOKEN_REFRESHED, SIGNED_OUT etc., try to reload
      void load();
    });
    return () => {
      sub?.subscription.unsubscribe();
    };
  }, []);

  // biome-ignore lint/correctness/useExhaustiveDependencies: load is recreated each render but behaves the same
  const value = useMemo<UserContextValue>(
    () => ({ loading, error, profile, userEmail, roleId, roleRank, refresh: load }),
    [loading, error, profile, userEmail, roleId, roleRank],
  );

  return <UserContext.Provider value={value}>{children}</UserContext.Provider>;
}

export function useUser(): UserContextValue {
  const ctx = useContext(UserContext);
  if (!ctx) {
    throw new Error("useUser must be used within a UserProvider");
  }
  return ctx;
}

"use client";

import { apiErrorMessage } from "@/lib/api-error-message";
import { type OrgMembership, orgSlugFromPath, repointOrgPath } from "@/lib/orgs/types";
import { createClient } from "@/lib/sb/client";
import { isSupabaseConfigured } from "@/lib/sb/config";
import { usePathname, useRouter } from "next/navigation";
import { createContext, useCallback, useContext, useEffect, useMemo, useState } from "react";

/**
 * The one source of truth for tenancy on the client.
 *
 * Aveiro grew a UserProvider that carried organizations AND a separate
 * OrganizationProvider, and the switcher then had two lists that could
 * disagree. There is one provider here, and `UserProvider` stays about the
 * person — profile, email, global role — and knows nothing about tenants.
 *
 * The URL is what selects the organization, not state held here: `selected`
 * is derived from the `[org]` segment. That way a link, a refresh and a back
 * button all land on the same tenant as a click on the switcher, and there
 * is no second place for the selection to drift out of sync.
 */
type OrgContextValue = {
  /** Every organization the signed-in user belongs to. Empty in demo mode. */
  organizations: OrgMembership[];
  /** The one the URL is pointing at, once it is known. */
  selected: OrgMembership | null;
  /**
   * The `[org]` segment itself. Available before `organizations` loads, and
   * in demo mode where there is no database to load them from — so this, not
   * `selected`, is what a link builds a path from.
   */
  slug: string | null;
  /** Go to the same page under another organization. */
  select: (slug: string) => void;
  loading: boolean;
  error: string | null;
  refresh: () => Promise<void>;
};

const OrgContext = createContext<OrgContextValue | undefined>(undefined);

export function OrgProvider({ children }: { children: React.ReactNode }) {
  // Demo mode (no Supabase env): there is nothing to fetch, so start settled
  // rather than showing a spinner that will never resolve.
  const configured = isSupabaseConfigured();
  const pathname = usePathname() ?? "";
  const router = useRouter();

  const [organizations, setOrganizations] = useState<OrgMembership[]>([]);
  const [loading, setLoading] = useState(configured);
  const [error, setError] = useState<string | null>(null);

  const slug = orgSlugFromPath(pathname);

  const load = useCallback(async () => {
    if (!configured) return;
    try {
      setLoading(true);
      setError(null);

      // No session cookie: signed out, and the request would only log a 401.
      const { data: session } = await createClient().auth.getSession();
      if (!session.session) {
        setOrganizations([]);
        return;
      }

      const res = await fetch("/api/orgs", { credentials: "include", cache: "no-store" });

      // Signed out, or a composition running without Supabase configured:
      // normal states, not errors worth putting in front of anybody.
      if (res.status === 401 || res.status === 503) {
        setOrganizations([]);
        return;
      }
      if (!res.ok) {
        const body = await res.json().catch(() => ({}));
        throw new Error(apiErrorMessage(body, `Request failed (${res.status})`));
      }

      const data = (await res.json()) as { organizations?: OrgMembership[] };
      setOrganizations(data.organizations ?? []);
    } catch (e) {
      setError(e instanceof Error ? e.message : "Failed to load your organizations");
      setOrganizations([]);
    } finally {
      setLoading(false);
    }
  }, [configured]);

  // `load` is stable, so this runs once per mount. The list changes when an
  // organization is created or left, and both of those call refresh(), and
  // when the session does: signing in navigates on the client, so the
  // provider is still mounted from the signed-out page.
  useEffect(() => {
    void load();
    if (!configured) return;
    const { data: sub } = createClient().auth.onAuthStateChange((event) => {
      if (event === "SIGNED_IN" || event === "SIGNED_OUT") void load();
    });
    return () => sub.subscription.unsubscribe();
  }, [configured, load]);

  const value = useMemo<OrgContextValue>(() => {
    const selected = organizations.find((org) => org.slug === slug) ?? null;

    return {
      organizations,
      selected,
      slug,
      // Switching is a re-root of the current path, not a jump to a fixed
      // landing page: whoever switches stays on the page they were reading.
      select: (next: string) => {
        if (next !== slug) router.push(repointOrgPath(pathname, next));
      },
      loading,
      error,
      refresh: load,
    };
  }, [organizations, slug, pathname, loading, error, router, load]);

  return <OrgContext.Provider value={value}>{children}</OrgContext.Provider>;
}

export function useOrg(): OrgContextValue {
  const ctx = useContext(OrgContext);
  if (!ctx) {
    throw new Error("useOrg must be used within an OrgProvider");
  }
  return ctx;
}

export * from "./Providers";
export * from "./UserProvider";
export * from "./OrgProvider";
export * from "./Mdx";
export * from "./LocaleProvider";

import type { NextRequest } from "next/server";
import { authProxy } from "@/lib/sb/proxy";

/**
 * Every request but static assets, through each slice's step in turn: the
 * i18n slice maps a language URL (`/hu/store`) onto the page it renders, then
 * the auth slice rate-limits and refreshes the Supabase session for that
 * page. A composition without one of them has its step unwired here.
 */
export async function proxy(request: NextRequest) {
  return authProxy(request);
}

export const config = {
  // Everything that can touch auth — API routes included — but not static
  // assets. Refreshing the session in exactly one layer (here) keeps
  // Supabase's single-use refresh-token rotation from being lost.
  matcher: [
    "/((?!_next/static|_next/image|favicon.ico|trademarks|images|.*\\.(?:svg|png|jpg|jpeg|gif|webp|ico|mp4)$).*)",
  ],
};

import { listUserOrganizations } from "@/lib/orgs/server";
import { DEMO_ORG_SLUG, orgPath } from "@/lib/orgs/types";
import { isSupabaseConfigured } from "@/lib/sb/config";
import { Column, Heading, Text } from "@once-ui-system/core";
import { redirect } from "next/navigation";

export const dynamic = "force-dynamic";

/**
 * `/app` — where a fresh sign-in lands, before anyone knows which tenant
 * they belong to.
 *
 * It resolves the user's organizations (creating their personal one on the
 * way, if this is their first authenticated request) and re-routes to the
 * first. Nothing renders here in the normal case; the org's own home is at
 * `/app/<slug>`.
 */
export default async function AppIndex() {
  // Demo mode: there is no database to ask, and the product shell renders
  // its sample data for any slug.
  if (!isSupabaseConfigured()) redirect(orgPath(DEMO_ORG_SLUG));

  const result = await listUserOrganizations();

  if (result.ok && result.organizations.length > 0) {
    redirect(orgPath(result.organizations[0].slug));
  }
  if (!result.ok && result.status === 401) {
    redirect("/auth");
  }

  // Everything above either redirected or failed for a reason worth showing.
  return (
    <Column fillWidth gap="8" paddingX="16" paddingY="64" horizontal="center">
      <Heading variant="heading-strong-l">No workspace yet</Heading>
      <Text align="center" onBackground="neutral-weak" variant="body-default-m">
        {result.ok ? "You are not a member of any organization." : result.error}
      </Text>
    </Column>
  );
}

import { requireOrg } from "@/lib/orgs/server";
import { isSupabaseConfigured } from "@/lib/sb/config";
import { notFound, redirect } from "next/navigation";

/**
 * The tenancy gate for everything under `/app/[org]`.
 *
 * The proxy already sends a signed-out visitor to `/auth`, but it only knows
 * whether there is a session — not whether this session belongs in THIS
 * organization. That question can only be answered against the database, so
 * it is answered here, once, for every page in the segment.
 *
 * A non-member gets a 404 rather than a 403: see the NOT_FOUND note in
 * src/lib/orgs/server.ts.
 */
export default async function OrgLayout({
  children,
  params,
}: {
  children: React.ReactNode;
  params: Promise<{ org: string }>;
}) {
  // Demo mode: no Supabase at all, so there is no membership to check and
  // nothing to leak. Every composition has to run with zero environment
  // variables, and the product shell renders its sample data for any slug.
  //
  // Configured-but-incomplete is NOT this case: the guard below answers 503
  // and the segment 404s, which is the direction a tenancy gate should fail.
  if (!isSupabaseConfigured()) return <>{children}</>;

  const { org } = await params;
  const guard = await requireOrg(org);

  if (!guard.ok) {
    if (guard.status === 401) redirect("/auth");
    notFound();
  }

  return <>{children}</>;
}

"use client";

import { kbar } from "@/content";
import { schema } from "@/resources";
import {
  Avatar,
  Background,
  Button,
  Column,
  Drawer,
