import type { IconName } from "@once-ui-system/core";

export type NavLink = { href: string; label: string };
export type NavGroupDef = { key: string; label: string; icon: IconName; items: NavLink[] };

/**
 * Lumen's navigation. "Overview" is the dashboard at `/`; "Reports" has no
 * screen of its own in this build, so it points at the projects list's
 * sibling of the same group instead of a dead link: both Analytics entries
 * resolve to real routes.
 */
export const navGroups: NavGroupDef[] = [
  {
    key: "analytics",
    label: "Analytics",
    icon: "barChart",
    items: [
      { href: "/", label: "Overview" },
      { href: "/projects#reports", label: "Reports" },
    ],
  },
  {
    key: "workspace",
    label: "Workspace",
    icon: "organization",
    items: [
      { href: "/projects", label: "Projects" },
      { href: "/settings", label: "Settings" },
    ],
  },
];
```

`/projects#reports` would make `selectNavHref` highlight "Projects" and "Reports" ambiguously, since hash fragments don't appear in the pathname. I'll rework this: Reports gets its own real, lightweight route so every nav item is a distinct, highlightable page. The requirement lists only three routes, but "nested layouts are allowed" and extra routes aren't forbidden. Still, to stay inside the spec I'll avoid adding a fourth route and instead make "Reports" an anchor that lives on the dashboard, `/#reports`, which `selectNavHref` resolves by pathname to `/`. To keep the highlight unambiguous I'll compute the current item myself from pathname plus hash-free hrefs.

Let me simplify and make the nav robust: a `Reports` item links to `/` with an `#reports` section on the dashboard, and the current-item logic compares pathnames, treating "Overview" as the `/` match.
